codeunit 70123 "CG Partial Record Loader"
{
    Access = Public;

    procedure GetCustomerNames(): List of [Text]
    var
        Customer: Record Customer;
        CustomerNames: List of [Text];
    begin
        Customer.SetLoadFields(Customer.Name);

        if Customer.FindSet() then
            repeat
                CustomerNames.Add(Customer.Name);
            until Customer.Next() = 0;

        exit(CustomerNames);
    end;

    procedure GetItemBasicInfo(var ItemList: List of [Text])
    var
        Item: Record Item;
    begin
        Clear(ItemList);

        Item.SetLoadFields(Item."No.", Item.Description);

        if Item.FindSet() then
            repeat
                ItemList.Add(StrSubstNo('%1: %2', Item."No.", Item.Description));
            until Item.Next() = 0;
    end;

    procedure SumItemInventory(): Decimal
    var
        Item: Record Item;
        TotalInventory: Decimal;
    begin
        Item.SetLoadFields(Item."No.");

        if Item.FindSet() then
            repeat
                Item.CalcFields(Item.Inventory);
                TotalInventory += Item.Inventory;
            until Item.Next() = 0;

        exit(TotalInventory);
    end;

    procedure CountBlockedCustomers(): Integer
    var
        Customer: Record Customer;
    begin
        Customer.SetRange(Customer.Blocked, Customer.Blocked::All);
        Customer.SetLoadFields(Customer."No.");

        exit(Customer.Count());
    end;

    procedure GetHighValueItems(MinPrice: Decimal): List of [Code[20]]
    var
        Item: Record Item;
        ItemNos: List of [Code[20]];
    begin
        Item.SetLoadFields(Item."No.", Item."Unit Price");

        if Item.FindSet() then
            repeat
                if Item."Unit Price" >= MinPrice then
                    ItemNos.Add(Item."No.");
            until Item.Next() = 0;

        exit(ItemNos);
    end;
}
