    Access = Public;

    var
        DivisionByZeroErr: Label 'Division by zero is not allowed.';

    [TryFunction]
    procedure TryDivide(Numerator: Decimal; Denominator: Decimal; var Result: Decimal)
    begin
        if Denominator = 0 then
