        Result := Numerator / Denominator;
    end;

    procedure SafeDivide(Numerator: Decimal; Denominator: Decimal; DefaultValue: Decimal): Decimal
    var
        Result: Decimal;
    begin
        if not TryDivide(Numerator, Denominator, Result) then
            exit(DefaultValue);

