            exit(DefaultValue);

        exit(ParsedValue);
    end;

    procedure ExecuteWithFallback(PrimaryValue: Decimal; FallbackValue: Decimal; Divisor: Decimal): Decimal
    var
        Result: Decimal;
    begin
