codeunit 70013 "CG Loop Utilities"
{
    // This codeunit demonstrates the use of the continue keyword in loops

    procedure SumPositiveNumbers(Numbers: List of [Decimal]): Decimal
    var
        Number: Decimal;
        Sum: Decimal;
    begin
        Sum := 0;

        foreach Number in Numbers do begin
            // Skip negative or zero numbers using continue
            if Number <= 0 then
                continue;

            Sum += Number;
        end;

        exit(Sum);
    end;

    procedure CountValidCodes(Codes: List of [Code[20]]): Integer
    var
        CodeValue: Code[20];
        Count: Integer;
    begin
        Count := 0;

        foreach CodeValue in Codes do begin
            // Skip empty codes using continue
            if CodeValue = '' then
                continue;

            Count += 1;
        end;

        exit(Count);
    end;

    procedure FilterAndProcess(Values: array[10] of Integer; Threshold: Integer): Text
    var
        i: Integer;
        ResultText: TextBuilder;
        FirstValueAdded: Boolean;
    begin
        FirstValueAdded := false;
        ResultText := ResultText.Create();

        for i := 1 to 10 do begin
            // Skip values at or below threshold using continue
            if Values[i] <= Threshold then
                continue;

            // Add comma separator for all values except the first one
            if FirstValueAdded then
                ResultText.Append(',');

            ResultText.Append(Format(Values[i]));
            FirstValueAdded := true;
        end;

        exit(ResultText.ToText());
    end;
}
