codeunit 70100 "Tax Calculator"
{
    Access = Public;

    procedure CalculateTax(Amount: Decimal; CountryCode: Code[2]; ProductType: Enum "CG Product Type"): Decimal
    var
        TaxRate: Decimal;
        TaxAmount: Decimal;
    begin
        // Edge cases: Negative or Zero amounts
        if Amount <= 0 then
            exit(0);

        // Normalize CountryCode to uppercase for consistent comparison
        CountryCode := UpperCase(CountryCode);

        case CountryCode of
            'US':
                begin
                    // US Rules: Based on Amount thresholds
                    if Amount < 100 then
                        TaxRate := 0
                    else
                        if Amount < 1000 then
                            TaxRate := 0.07
                        else
                            TaxRate := 0.085;
                end;
            'DE':
                begin
                    // Germany Rules: Based on ProductType
                    if ProductType = ProductType::Food then
                        TaxRate := 0.07
                    else
                        TaxRate := 0.19;
                end;
            'UK':
                begin
                    // United Kingdom Rules: Based on ProductType
                    if ProductType = ProductType::Books then
                        TaxRate := 0
                    else
                        TaxRate := 0.20;
                end;
            else
                // Other countries: No tax calculation available
                TaxRate := 0;
        end;

        TaxAmount := Amount * TaxRate;
        exit(Round(TaxAmount, 0.01));
    end;
}
