codeunit 70210 "CG Validation Engine"
{
    Access = Public;

    procedure CreateValidationError(ErrorCode: Enum "CG Validation Error"; FieldName: Text; ErrorMessage: Text): ErrorInfo
    var
        ErrorInfoLocal: ErrorInfo;
    begin
        ErrorInfoLocal.Message(ErrorMessage);
        ErrorInfoLocal.CustomDimensions.Add('ErrorCode', Format(ErrorCode.AsInteger()));
        ErrorInfoLocal.CustomDimensions.Add('FieldName', FieldName);
        ErrorInfoLocal.Collectible(IsCollectingErrors());
        exit(ErrorInfoLocal);
    end;

    procedure GetErrorCode(ErrInfo: ErrorInfo): Enum "CG Validation Error"
    var
        ErrorCodeValue: Text;
    begin
        if ErrInfo.CustomDimensions.ContainsKey('ErrorCode') then begin
            ErrorCodeValue := ErrInfo.CustomDimensions.Get('ErrorCode');
            exit(Enum::"CG Validation Error".FromInteger(ErrorCodeValue.ToInteger()));
        end;
        exit(Enum::"CG Validation Error"::None);
    end;

    procedure ValidateNotEmpty(Value: Text; FieldName: Text)
    begin
        if Value.IsEmpty() then
            Error(CreateValidationError(Enum::"CG Validation Error"::EmptyField, FieldName, 'Field cannot be empty'));
    end;

    procedure ValidateInRange(Value: Decimal; MinValue: Decimal; MaxValue: Decimal; FieldName: Text)
    var
        ErrorMessage: Text;
    begin
        if (Value < MinValue) or (Value > MaxValue) then begin
            ErrorMessage := StrSubstNo('Value must be between %1 and %2', MinValue, MaxValue);
            Error(CreateValidationError(Enum::"CG Validation Error"::OutOfRange, FieldName, ErrorMessage));
        end;
    end;
}
