codeunit 70121 "CG JSON Config Handler"
{
    Access = Public;

    procedure ParseJsonConfig(JsonText: Text) JsonConfig: JsonObject
    begin
        if not JsonConfig.ReadFrom(JsonText) then
            Error('Invalid JSON configuration: %1', JsonText);
    end;

    procedure CreateJsonFromSettings(Settings: Dictionary of [Text, Text]) JsonConfig: JsonObject
    var
        SettingsKey: Text;
        SettingsValue: Text;
    begin
        foreach SettingsKey in Settings.Keys() do begin
            SettingsValue := Settings.Get(SettingsKey);
            JsonConfig.Add(SettingsKey, SettingsValue);
        end;
    end;

    procedure MergeJsonConfigs(BaseJson: JsonObject; OverrideJson: JsonObject) MergedJson: JsonObject
    var
        JsonKey: Text;
        JsonToken: JsonToken;
    begin
        foreach JsonKey in BaseJson.Keys() do
            if BaseJson.Get(JsonKey, JsonToken) then
                MergedJson.Add(JsonKey, JsonToken.Clone());

        foreach JsonKey in OverrideJson.Keys() do
            if OverrideJson.Get(JsonKey, JsonToken) then begin
                if MergedJson.Contains(JsonKey) then
                    MergedJson.Remove(JsonKey);

                MergedJson.Add(JsonKey, JsonToken.Clone());
            end;
    end;

    procedure GetStringValue(Json: JsonObject; JsonKey: Text): Text
    var
        JsonToken: JsonToken;
        JsonValue: JsonValue;
    begin
        if Json.Get(JsonKey, JsonToken) then begin
            JsonValue := JsonToken.AsValue();
            exit(JsonValue.AsText());
        end;

        exit('');
    end;

    procedure GetIntValue(Json: JsonObject; JsonKey: Text): Integer
    var
        JsonToken: JsonToken;
        JsonValue: JsonValue;
    begin
        if Json.Get(JsonKey, JsonToken) then begin
            JsonValue := JsonToken.AsValue();
            exit(JsonValue.AsInteger());
        end;

        exit(0);
    end;
}END-CODE

