codeunit 70018 "CG Request Builder"
{
    Access = Public;

    var
        RequestUrl: Text;
        RequestMethod: Text;
        RequestHeaders: Dictionary of [Text, Text];
        RequestBody: Text;
        RequestTimeout: Integer;

    procedure SetUrl(Url: Text): Codeunit "CG Request Builder"
    begin
        RequestUrl := Url;
        exit(Rec);
    end;

    procedure SetMethod(Method: Text): Codeunit "CG Request Builder"
    begin
        RequestMethod := Method;
        exit(Rec);
    end;

    procedure AddHeader(Name: Text; Value: Text): Codeunit "CG Request Builder"
    begin
        RequestHeaders.Set(Name, Value);
        exit(Rec);
    end;

    procedure SetBody(Body: Text): Codeunit "CG Request Builder"
    begin
        RequestBody := Body;
        exit(Rec);
    end;

    procedure SetTimeout(Timeout: Integer): Codeunit "CG Request Builder"
    begin
        RequestTimeout := Timeout;
        exit(Rec);
    end;

    procedure Build(): Text
    var
        Result: TextBuilder;
        Key: Text;
        Value: Text;
    begin
        Result.AppendLine('URL: ' + RequestUrl);
        Result.AppendLine('Method: ' + RequestMethod);

        if RequestHeaders.Count() > 0 then begin
            foreach Key in RequestHeaders.Keys do begin
                RequestHeaders.Get(Key, Value);
                Result.AppendLine(StrSubstNo('%1: %2', Key, Value));
            end;
        end;

        if RequestBody <> '' then
            Result.AppendLine('Body: ' + RequestBody);

        if RequestTimeout > 0 then
            Result.AppendLine('Timeout: ' + Format(RequestTimeout));

        exit(Result.ToText());
    end;

    procedure Create(): Codeunit "CG Request Builder"
    begin
        Clear(RequestUrl);
        Clear(RequestMethod);
        Clear(RequestHeaders);
        Clear(RequestBody);
        Clear(RequestTimeout);
        exit(Rec);
    end;
}

