    var
        TaxAmount: Decimal;
    begin
        if Amount <= 0 then
            exit(0);

        case CountryCode of
            'US':
                begin
                    if Amount < 100 then
                        TaxAmount := 0
                    else
                        if Amount < 1000 then
                            TaxAmount := Amount * 0.07
                        else
                            TaxAmount := Amount * 0.085;
                end;
            'DE':
                begin
                    if ProductType = ProductType::Food then
                        TaxAmount := Amount * 0.07
                    else
                        TaxAmount := Amount * 0.19;
                end;
            'UK':
                begin
                    if ProductType = ProductType::Books then
                        TaxAmount := 0
                    else
                        TaxAmount := Amount * 0.20;
                end;
            else
                TaxAmount := 0;
        end;

        exit(Round(TaxAmount, 0.01));
    end;
