codeunit 70051 "CG Number Sequence"
{
    Access = Public;

    procedure IncrementByStep(Value: Text; Step: Integer): Text
    var
        Prefix: Text;
        NumStr: Text;
        Num: Integer;
        i: Integer;
        Len: Integer;
    begin
        Len := StrLen(Value);
        i := Len;
        while (i > 0) and (Value[i] >= '0') and (Value[i] <= '9') do
            i := i - 1;
        Prefix := CopyStr(Value, 1, i);
        NumStr := CopyStr(Value, i + 1, Len - i);
        if not Evaluate(Num, NumStr) then
            Error('Invalid number in string');
        Num := Num + Step;
        NumStr := Format(Num, 0, StrLen(NumStr));
        exit(Prefix + NumStr);
    end;

    procedure GenerateSequence(StartValue: Text; Count: Integer): List of [Text]
    var
        Result: List of [Text];
        Current: Text;
        i: Integer;
    begin
        Current := StartValue;
        for i := 1 to Count do begin
            Result.Add(Current);
            Current := IncrementByStep(Current, 1);
        end;
        exit(Result);
    end;

    procedure GenerateBatchNumbers(Prefix: Text; StartNum: Integer; BatchSize: Integer; Increment: Integer): List of [Text]
    var
        Result: List of [Text];
        CurrentNum: Integer;
        i: Integer;
    begin
        CurrentNum := StartNum;
        for i := 1 to BatchSize do begin
            Result.Add(Prefix + Format(CurrentNum, 0, 4));
            CurrentNum := CurrentNum + Increment;
        end;
        exit(Result);
    end;

    procedure DecrementValue(Value: Text): Text
    begin
        exit(IncrementByStep(Value, -1));
    end;
}
