            'UK':
                case ProductType of
                    "CG Product Type"::Books:
                        Tax := 0;
                    else
                        Tax := Amount * 0.20;
                end;
            else
                Tax := 0;
        end;

        exit(Round(Tax, 0.01));
    end;
