        DiscountAmount: Decimal;
        Net: Decimal;
        AdjustedDiscountPercent: Decimal;
    begin
        // Validate inputs
        if (UnitPrice < 0) or (Quantity < 0) or (DiscountPercent < 0) or (RoundingPrecision < 0) then
            error('Inputs cannot be negative');

        if RoundingPrecision = 0 then
            error('Rounding precision must be greater than zero');

        // Handle zero cases
        if (UnitPrice = 0) or (Quantity = 0) then
            exit(0);

        // Normalize discount percentage
        AdjustedDiscountPercent := DiscountPercent;
        if AdjustedDiscountPercent > 100 then
            AdjustedDiscountPercent := 100;

        // Calculate line amounts
        Gross := UnitPrice * Quantity;
        DiscountAmount := Round(Gross * (AdjustedDiscountPercent / 100), RoundingPrecision, '=');
        Net := Gross - DiscountAmount;

        // Round final result
        Result := Round(Net, RoundingPrecision, '=');

        // Raise integration event
        OnAfterCalculateLineAmount(Result, UnitPrice, Quantity, DiscountPercent, RoundingPrecision);

        exit(Result);
    end;

    [IntegrationEvent(false, false)]
    procedure OnAfterCalculateLineAmount(var Result: Decimal; UnitPrice: Decimal; Quantity: Decimal; DiscountPercent: Decimal; RoundingPrecision: Decimal)
    begin
    end;
