            procedure BuildDynamicFilter(var RecRef: RecordRef; FilterCriteria: Dictionary of [Text, Text]): Boolean
            var
                FldRef: FieldRef;
                KeyName: Text;
                FilterExpr: Text;
                i: Integer;
