            begin
                foreach KeyName in FilterCriteria.Keys do begin
                    FieldFound := false;
                    for i := 1 to RecRef.FieldCount do begin
                        FldRef := RecRef.FieldIndex(i);
                        if FldRef.Name = KeyName then begin
                            FilterCriteria.Get(KeyName, FilterExpr);
                            FldRef.SetFilter(FilterExpr);
