    procedure GetRecordByPrimaryKey(TableId: Integer; KeyValues: List of [Text]; var ResultRecRef: RecordRef): Boolean
    var
        KeyRef: KeyRef;
        FldRef: FieldRef;
        i: Integer;
        KeyValue: Text;
    begin
        ResultRecRef.Open(TableId);
        KeyRef := ResultRecRef.KeyIndex(1);

        if KeyRef.FieldCount <> KeyValues.Count then
            exit(false);

        for i := 1
to KeyRef.FieldCount do begin
            FldRef := KeyRef.FieldIndex(i);
            KeyValues.Get(i, KeyValue);
            Evaluate(FldRef, KeyValue);
        end;

        exit(ResultRecRef.Find('='));
    end;

    procedure TransformRecord(var RecRef: RecordRef; Transformer: Interface "IFieldTransformer"): Integer
    var
        FldRef: FieldRef;
        i: Integer;
        TransformedCount: Integer;
        OldValue: Variant;
        NewValue: Variant;
    begin
        TransformedCount := 0;
        for i := 1 to RecRef.FieldCount do begin
            FldRef := RecRef.FieldIndex(i);
            if FldRef.Class = FieldClass::Normal then begin
                OldValue := FldRef.Value;
                NewValue := Transformer.Transform(FldRef);

                if Format(OldValue) <> Format(NewValue) then begin
                    FldRef.Value := NewValue;
                    TransformedCount += 1;
                end;
            end;
        end;
        exit(TransformedCount);
    end;

    procedure FindRelatedRecords(SourceRecRef: RecordRef; RelatedTableId: Integer): List of [RecordId]
    var
        RelatedRecRef: RecordRef;
        FldRef: FieldRef;
        SourceKeyRef: KeyRef;
        SourceFldRef: FieldRef;
        SourcePKValue: Variant;
        i: Integer;
        ResultList: List of [RecordId];
    begin
        SourceKeyRef := SourceRecRef.KeyIndex(1);
        if SourceKeyRef.FieldCount = 0 then
            exit(ResultList);

        SourceFldRef := SourceKeyRef.FieldIndex(1);
        SourcePKValue := SourceFldRef.Value;

        RelatedRecRef.Open(RelatedTableId);
        for i := 1 to RelatedRecRef.FieldCount do begin
            FldRef := RelatedRecRef.FieldIndex(i);
            if FldRef.Relation = SourceRecRef.Number then begin
                FldRef.SetRange(SourcePKValue);
                if RelatedRecRef.FindSet() then
                    repeat
                        if not ResultList.Contains(RelatedRecRef.RecordId) then
                            ResultList.Add(RelatedRecRef.RecordId);
                    until RelatedRecRef.Next() = 0;
                FldRef.SetRange();
            end;
        end;
        RelatedRecRef.Close();

        exit(ResultList);
    end;

    procedure ValidateRecordCompleteness(RecRef: RecordRef; RequiredFieldNos: List of [Integer]): List of [Text]
    var
        FldRef: FieldRef;
        FieldNo: Integer;
        MissingFields: List of [Text];
        IsEmpty: Boolean;
        TextVal: Text;
        IntVal: Integer;
        DecVal: Decimal;
        DateVal: Date;
    begin
        foreach FieldNo in RequiredFieldNos do begin
            if RecRef.FieldExist(FieldNo) then begin
                FldRef := RecRef.Field(FieldNo);
                IsEmpty := false;

                case FldRef.Type of
                    FieldType::Text, FieldType::Code:
                        begin
                            TextVal := Format(FldRef.Value);
                            if TextVal = '' then
                                IsEmpty := true;
                        end;
                    FieldType::Integer:
                        begin
                            IntVal := FldRef.Value;
                            if IntVal = 0 then
                                IsEmpty := true;
                        end;
                    FieldType::Decimal:
                        begin
                            DecVal := FldRef.Value;
                            if DecVal = 0 then
                                IsEmpty := true;
                        end;
                    FieldType::Date:
                        begin
                            DateVal := FldRef.Value;
                            if DateVal = 0D then
                                IsEmpty := true;
                        end;
                end;

                if IsEmpty then
                    MissingFields.Add(FldRef.Name);
            end;
        end;

        exit(MissingFields);
    end;
}

